const delimiter = Buffer.from("\r\n--XYZ");
const chunks = [Buffer.from("ABCDEF\r\n-"), Buffer.from("-XYZ--\r\n")];

let pending = Buffer.alloc(0);
const written: string[] = [];
for (const chunk of chunks) {
  pending = Buffer.concat([pending, chunk]);
  const at = pending.indexOf(delimiter);
  if (at === -1) {
    const safe = pending.length - (delimiter.length - 1);
    written.push(pending.subarray(0, safe).toString());
    pending = pending.subarray(safe);
  } else {
    written.push(pending.subarray(0, at).toString());
    break;
  }
}
