function boundaryFrom(contentType: string | undefined): string {
  const match = /^multipart\/form-data;\s*boundary=(?:"([^"]{1,70})"|([^\s;]{1,70}))$/i.exec(contentType ?? "");
  const boundary = match?.[1] ?? match?.[2];
  if (boundary === undefined) throw new Error("not multipart");
  return boundary;
}

for (const header of ["multipart/form-data; boundary=----abc123", 'multipart/form-data; boundary="x y"', "application/json", undefined]) {
  try {
    console.log(boundaryFrom(header));
  } catch (error) {
    console.log(error instanceof Error ? error.message : error);
  }
}

