function makeCounter(limit: number) {
  let size = 0;
  return {
    add(chunk: Uint8Array): number {
      size += chunk.length;
      if (size > limit) throw new Error(`413: over ${limit} bytes`);
      return size;
    },
  };
}

const counter = makeCounter(8);
try {
  for (const chunk of [new Uint8Array(3), new Uint8Array(5), new Uint8Array(1)]) console.log("total", counter.add(chunk));
} catch (error) {
  console.log(error instanceof Error ? error.message : error);
}

