function sign(path: string, expires: number): string {
  let hash = 0;
  for (const char of `${path}\n${expires}\nserver-secret`) hash = (hash * 31 + char.charCodeAt(0)) >>> 0;
  return hash.toString(16);
}

function isValid(path: string, expires: number, sig: string, now: number): boolean {
  return sig === sign(path, expires) && now < expires;
}

const sig = sign("/files/9b2c.jpg", 1_000);
