type ImageType = "image/jpeg" | "image/png" | "image/webp";

const EXTENSIONS: Record<ImageType, string> = { "image/jpeg": ".jpg", "image/png": ".png", "image/webp": ".webp" };

function storageKey(productId: number, id: string, type: ImageType, clientName: string): string {
  return `products/${productId}/${id}${EXTENSIONS[type]}`;
}

console.log(storageKey(7, "5f0c", "image/png", "../../evil.html"));
console.log(storageKey(12, "9b2c", "image/jpeg", "rice.png"));
